/// Controller states (= asils.fsw.modes order).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Mode {
    Detumble = 0,
    NadirMtq = 1,
    NadirFine = 2,
    TargetFine = 3,
    SlewFine = 4,
    Spinup = 5,
    SunSpin = 6,
    DetumbleRcs = 7,
    SunAcqRotor = 8,
    SunMtq = 9,
    SunFine = 10,
}

impl Mode {
    pub fn from_u8(v: u8) -> Option<Mode> {
        match v {
            0 => Some(Mode::Detumble),
            1 => Some(Mode::NadirMtq),
            2 => Some(Mode::NadirFine),
            3 => Some(Mode::TargetFine),
            4 => Some(Mode::SlewFine),
            5 => Some(Mode::Spinup),
            6 => Some(Mode::SunSpin),
            7 => Some(Mode::DetumbleRcs),
            8 => Some(Mode::SunAcqRotor),
            9 => Some(Mode::SunMtq),
            10 => Some(Mode::SunFine),
            _ => None,
        }
    }
}

