        if !self.detumble_hold_s.is_finite() || self.detumble_hold_s > 1e15 || self.detumble_hold_s < -1e15 || (self.detumble_hold_s != 0.0 && self.detumble_hold_s < 1e-30 && self.detumble_hold_s > -1e-30) || self.detumble_hold_s < 0.0 { return Err("detumble_hold_s"); }
