        if !self.mtq_err_max.is_finite() || self.mtq_err_max > 1e15 || self.mtq_err_max < -1e15 || (self.mtq_err_max != 0.0 && self.mtq_err_max < 1e-30 && self.mtq_err_max > -1e-30) { return Err("mtq_err_max"); }
